from dataclasses import dataclass, replace
from enum import Enum, auto, unique


@unique
class EnrollmentStatus(Enum):
    ACTIVE = auto()
    SUSPENDED = auto()
    GRADUATED = auto()


@dataclass(frozen=True)
class StudentProfile:
    student_id: str
    name: str
    status: EnrollmentStatus = EnrollmentStatus.ACTIVE

    def __post_init__(self) -> None:
        object.__setattr__(self, "student_id", self.student_id.strip())
        object.__setattr__(self, "name", self.name.strip())
        if not self.student_id or not self.name:
            raise ValueError("student_id and name cannot be blank")
        if not isinstance(self.status, EnrollmentStatus):
            raise TypeError("status must be EnrollmentStatus")


ALLOWED_TRANSITIONS = {
    EnrollmentStatus.ACTIVE: {EnrollmentStatus.SUSPENDED, EnrollmentStatus.GRADUATED},
    EnrollmentStatus.SUSPENDED: {EnrollmentStatus.ACTIVE, EnrollmentStatus.GRADUATED},
    EnrollmentStatus.GRADUATED: set(),
}


def parse_status(text: str) -> EnrollmentStatus:
    if not isinstance(text, str):
        raise TypeError("status text must be str")
    try:
        return EnrollmentStatus[text.strip().upper()]
    except KeyError as error:
        raise ValueError("unknown status") from error


def move_to(profile: StudentProfile, target: EnrollmentStatus) -> StudentProfile:
    if not isinstance(target, EnrollmentStatus):
        raise TypeError("target must be EnrollmentStatus")
    if target == profile.status:
        return profile
    if target not in ALLOWED_TRANSITIONS[profile.status]:
        raise ValueError(f"cannot move from {profile.status.name} to {target.name}")
    return replace(profile, status=target)


def expect(error_type: type[BaseException], action) -> None:
    try:
        action()
    except error_type:
        return
    raise AssertionError(f"expected {error_type.__name__}")


def run_checks() -> None:
    assert [status.name for status in EnrollmentStatus] == ["ACTIVE", "SUSPENDED", "GRADUATED"]
    assert parse_status(" active ") is EnrollmentStatus.ACTIVE

    original = StudentProfile(" S01 ", " Amy ")
    suspended = move_to(original, EnrollmentStatus.SUSPENDED)
    active_again = move_to(suspended, EnrollmentStatus.ACTIVE)
    graduated = move_to(active_again, EnrollmentStatus.GRADUATED)
    assert original.status is EnrollmentStatus.ACTIVE
    assert suspended.status is EnrollmentStatus.SUSPENDED
    assert graduated.status is EnrollmentStatus.GRADUATED
    assert move_to(graduated, EnrollmentStatus.GRADUATED) is graduated

    expect(ValueError, lambda: move_to(graduated, EnrollmentStatus.ACTIVE))
    expect(ValueError, lambda: parse_status("unknown"))
    expect(TypeError, lambda: move_to(original, "SUSPENDED"))
    expect(TypeError, lambda: StudentProfile("S02", "Bo", "ACTIVE"))
    expect(ValueError, lambda: StudentProfile("", "Bo"))


if __name__ == "__main__":
    run_checks()
    print("enum-status checks: OK")
